#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT Sound : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url [
      "media/bad.mid",
      "media/bad2.mid"
    ]
    loop TRUE
    startTime 946684800.048
    stopTime 1
  }
}

DEF L LoadSensor {
  children USE O
}

DEF PL Script {
  inputOnly SFBool  a
  inputOnly SFBool  l
  inputOnly SFFloat p
  inputOnly SFTime  t

  url "ecmascript:
function a (v, t) { print ('L isActive ' + v + ' ' + t); }
function l (v, t) { print ('L isLoaded ' + v + ' ' + t); }
function p (v, t) { print ('L progress ' + v + ' ' + t); }
function t (v, t) { print ('L loadTime ' + v + ' ' + t); }
"
}

DEF PO Script {
  inputOnly SFBool a
  inputOnly SFTime d

  url "javascript:
function a (v, t) { print ('O active ' + v + ' ' + t); }
function d (v, t) { print ('O duration ' + v + ' ' + t); }
"
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

ROUTE L.isActive TO PL.a
ROUTE L.isLoaded TO PL.l
ROUTE L.progress TO PL.p
ROUTE L.loadTime TO PL.t
ROUTE O.isActive TO PO.a
ROUTE O.duration_changed TO PO.d
ROUTE T.time TO S.set_time
ROUTE S.start TO O.set_startTime
